 * Runs the instant-runoff count for a parsed election and returns the
 * per-round results plus the eventual winner (or null when there is none).
 */

export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  let round = 1
  let winner = null

  for (;;) {
    const tally = new Map()
    for (const c of continuing) tally.set(c, 0)
    let exhausted = 0

    for (const b of ballots) {
      const chosen = b.names.find((n) => continuing.has(n))
      if (chosen !== undefined) {
        tally.set(chosen, tally.get(chosen) + b.count)
      } else {
        exhausted += b.count
      }
    }

    for (const c of continuing) history.get(c).push(tally.get(c))

    const activeTotal = [...tally.values()].reduce((a, b) => a + b, 0)

    const entries = [...continuing].map((c) => ({ name: c, votes: tally.get(c) }))
    entries.sort((a, b) => b.votes - a.votes || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))

    if (activeTotal === 0) {
      rounds.push({ number: round, entries, exhausted, eliminated: null })
      winner = null
      break
    }

    const majority = entries.find((e) => e.votes * 2 > activeTotal)
    if (majority) {
      rounds.push({ number: round, entries, exhausted, eliminated: null })
      winner = majority.name
      break
    }

    const minVotes = Math.min(...entries.map((e) => e.votes))
    const tied = entries.filter((e) => e.votes === minVotes).map((e) => e.name)
    const elim = tied.length === 1 ? tied[0] : tieBreak(tied, history, round)

    rounds.push({ number: round, entries, exhausted, eliminated: elim })
    continuing.delete(elim)
    round++
  }

  return { rounds, winner }
}

function tieBreak(tied, history, currentRound) {
  let remaining = tied.slice()
  for (let r = 1; r <= currentRound; r++) {
    if (remaining.length === 1) break
    const vals = remaining.map((c) => history.get(c)[r - 1])
    const minV = Math.min(...vals)
    remaining = remaining.filter((c, idx) => vals[idx] === minV)
  }
  if (remaining.length === 1) return remaining[0]
  remaining.sort()
  return remaining[remaining.length - 1]
}
